# Importacion masiva de usuarios por CSV (backend + pantalla Usuarios). Ejecutar desde la raiz del repo.
$ErrorActionPreference = 'Stop'
$b0 = ""
[IO.File]::WriteAllBytes((Join-Path (Get-Location) 'backend\src\routes\usuarios.js'), [Convert]::FromBase64String($b0))
$b1 = ""
[IO.File]::WriteAllBytes((Join-Path (Get-Location) 'frontend\src\pages\admin\Usuarios.jsx'), [Convert]::FromBase64String($b1))
Write-Host 'Listo. Haz git add -A; git commit; git push y espera el deploy de Render y GitHub Pages.'